using UnityEngine; using UnityEngine.Rendering; using UnityEngine.Rendering.HighDefinition; using System.Text;
public static class HdrpDoorDiag { public static void Run() { var sb = new StringBuilder();
 var box = new Bounds(new Vector3(0, 4.4f, 27.5f), new Vector3(4.4f, 5.2f, 3f));
 foreach (var r in Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None)) { if (!r.bounds.Intersects(box)) continue; if (r.bounds.size.x > 30f) { sb.AppendLine("BIG " + r.name + " size=" + r.bounds.size + " mat=" + (r.sharedMaterial != null ? r.sharedMaterial.name + "/" + r.sharedMaterial.shader.name : "null") + " act=" + r.gameObject.activeInHierarchy); continue; } sb.AppendLine(r.name + " root=" + r.transform.root.name + " act=" + r.gameObject.activeInHierarchy + " en=" + r.enabled + " ctr=" + r.bounds.center + " size=" + r.bounds.size + " mat=" + (r.sharedMaterial != null ? r.sharedMaterial.name + "/" + r.sharedMaterial.shader.name : "null")); }
 var prof = AssetDatabaseLoad(); if (prof != null) { if (prof.TryGet(out Fog f)) sb.AppendLine("fog colorMode=" + f.colorMode.value + " tint=" + f.tint.value + " maxDist=" + f.maxFogDistance.value + " base=" + f.baseHeight.value + " maxH=" + f.maximumHeight.value + " mfp=" + f.meanFreePath.value); if (prof.TryGet(out GradientSky g)) sb.AppendLine("gsky top=" + g.top.value + " mid=" + g.middle.value + " bot=" + g.bottom.value + " exp=" + g.exposure.value + " active=" + g.active); if (prof.TryGet(out VisualEnvironment v)) sb.AppendLine("env skyType=" + v.skyType.value + " cloud=" + v.cloudType.value); }
 System.IO.File.WriteAllText("Shots/_door_diag.txt", sb.ToString()); }
 static VolumeProfile AssetDatabaseLoad() { return UnityEditor.AssetDatabase.LoadAssetAtPath<VolumeProfile>("Assets/HDRP/Global.asset"); } }
